return allChannelsSliceValuesAtOutputCell.map((sliceValuesInChannel, channelIndex) =>
    sliceValuesInChannel.map((sliceValue, sliceIndex) => {
        const targetValue = allChannelsTargetValuesAtOutputCell[channelIndex];
        const blockX = conditionalBlockX[channelIndex][sliceIndex];
        const blockComp2PreX = conditionalBlockcomp_2_pre_X[channelIndex][sliceIndex];

        let gradient = 0;

        if (targetValue === 0) {
            // If the target is 0 and blockX is 1, gradient is 0 (blocked/stopped)
            if (blockX === 1) {
                gradient = 0;
            } else {
                // If target is 0 and not blocked, gradient is sliceValue - targetValue (which is sliceValue)
                gradient = sliceValue - targetValue;
            }
        } else if (targetValue === 1) {
            // If the target is 1, a special logic applies, primarily to slice 0
            if (sliceIndex === 0 && blockComp2PreX === 1) {
                // For slice 0, if comp_2_pre_X indicates 'translated', apply scaled error
                gradient = 3 * (targetValue - sliceValue);
            } else {
                // For other slices, or if slice 0 doesn't meet the comp_2_pre_X condition, gradient is 0
                gradient = 0;
            }
        }
        // conditionalBlockY is currently unused as its specific role is not yet inferred from examples.
        // Assuming targetValue is exclusively 0 or 1 based on current examples.

        return gradient;
    })
);

